INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35311, 'Luke 3:2', 'Luke', 3, 2, 'او حناس او قیافا لوی کاهنان وو، په هغه وخت کې د خدای کلام په دښته کې د زکریا په زوی یحیی باندې نازل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_2.mp3', '', 1761754199, 1761754199),
(35312, 'Luke 3:3', 'Luke', 3, 3, 'نو یحیی د اردن د سیند شاوخوا ټوله سیمه کې ګرځېده او وعظ یې کاوه چې د خپلو ګناهونو د بخښنې په خاطر توبه وباسئ او د تعمید غسل واخلئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_3.mp3', '', 1761754199, 1761754199),
(35313, 'Luke 3:4', 'Luke', 3, 4, 'لکه څنګه چې د اشعیا پیغمبر په کتاب کې لیکل شوي دي: یو څوک چیغې وهي دښته کې کړئ تیاره د څښتن دپاره لاره لاره کړئ سمه د هغه دپاره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_4.mp3', '', 1761754199, 1761754199),
(35314, 'Luke 3:5', 'Luke', 3, 5, 'ډکه به شي هره دره هواره به شي هره غونډۍ او غر کږې لارې به شي سمې او شي به هوار کنډ او کپر ځایونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_5.mp3', '', 1761754199, 1761754199),
(35315, 'Luke 3:6', 'Luke', 3, 6, 'بیا به وویني ټول انسانان د خدای خلاصون', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_6.mp3', '', 1761754199, 1761754199),
(35316, 'Luke 3:7', 'Luke', 3, 7, 'یحیی هغو ګڼ شمېر خلکو ته چې د هغه په لاس د تعمید غسل اخیستلو ته راغلي وو، وویل: «ای د مارانو بچیانو! تاسو چا خبر کړئ چې د راتلونکي غضب څخه وتښتئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_7.mp3', '', 1761754199, 1761754199),
(35317, 'Luke 3:8', 'Luke', 3, 8, 'نو بیا داسې کارونه وکړئ، ترڅو دا وښایي چې تاسو د ګناهونو نه توبه ویستلې ده. د خپلو ځانونو سره داسې مه وایئ چې ابراهیم زمونږ پلار دی. ځکه چې زه درته وایم چې خدای کولای شي د دې تیږو څخه هم ابراهیم ته اولادونه پیدا کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_8.mp3', '', 1761754199, 1761754199),
(35318, 'Luke 3:9', 'Luke', 3, 9, 'همدا‌اوس د ونو بېخونو ته تبر نیول شوی دی او هره ونه چې ښه مېوه نه نیسي، هغه به ووهل شي او په اور کې به واچول شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_9.mp3', '', 1761754199, 1761754199),
(35319, 'Luke 3:10', 'Luke', 3, 10, 'خلکو د هغه څخه پوښتنه وکړه: «نو بیا مونږ څه وکړو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_10.mp3', '', 1761754199, 1761754199),
(35320, 'Luke 3:11', 'Luke', 3, 11, 'هغه ځواب ورکړ: «څوک چې دوه کمیسونه لري، نو یو دې هغه چاته ورکړي چې نه یې لري او همدارنګه چا سره چې خواړه وي هغه دې هم د نورو سره ووېشي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_11.mp3', '', 1761754199, 1761754199),
(35321, 'Luke 3:12', 'Luke', 3, 12, 'مالیه ټولوونکي هم د تعمید د غسل اخیستلو دپاره راغلل او پوښتنه یې ترې وکړه: «ای استاذه! مونږ باید څه وکړو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_12.mp3', '', 1761754199, 1761754199),
(35322, 'Luke 3:13', 'Luke', 3, 13, 'هغه ځواب ورکړ: «د ټاکل شوې اندازې څخه زیاته مالیه مه اخلئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_13.mp3', '', 1761754199, 1761754199),
(35323, 'Luke 3:14', 'Luke', 3, 14, 'همدارنګه ځینو عسکرو هم ورڅخه پوښتنه وکړه: «او مونږ څه وکړو؟» هغوی ته یې وویل: «د چا څخه په زوره پیسې مه اخلئ او په هېچا باندې په دروغو تور مه لګوئ. په خپله تنخوا باندې قناعت وکړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_14.mp3', '', 1761754199, 1761754199),
(35324, 'Luke 3:15', 'Luke', 3, 15, 'خلکو انتظار کاوه او په خپلو زړونو کې یې د یحیی په هکله فکر کاوه چې هغه به مسیح وي که نه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_15.mp3', '', 1761754199, 1761754199),
(35325, 'Luke 3:16', 'Luke', 3, 16, 'نو یحیی هغوی ټولو ته وویل: «زه تاسو ته په اوبو باندې د تعمید غسل درکوم، خو یو څوک راروان دی چې هغه زما څخه ډېر زورور دی. زه حتی د دې لایق هم نه یم چې د هغه د څپلیو تسمې خلاصې کړم. هغه به تاسو ته په روح القدس او په اور باندې د تعمید غسل درکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_16.mp3', '', 1761754199, 1761754199),
(35326, 'Luke 3:17', 'Luke', 3, 17, 'هغه خپله ښاخۍ په لاس کې نیولې ده چې خپل درمند پاک کړي او غنم په خپل ګودام کې سره راټول کړي، خو بوس به په هغه اور کې سوځوي چې هېڅکله نه مړ کیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_17.mp3', '', 1761754199, 1761754199),
(35327, 'Luke 3:18', 'Luke', 3, 18, 'یحیی په ډېرو نورو طریقو خلک هڅول او هغوی ته یې زېری اوراوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_18.mp3', '', 1761754199, 1761754199),
(35328, 'Luke 3:19', 'Luke', 3, 19, 'خو یحیی هیرودیس والي د خپلې ورېندارې هیرودیا سره د ناروا اړیکو درلودلو او نورو ټولو بدو کارونو له امله ملامت کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_19.mp3', '', 1761754199, 1761754199),
(35329, 'Luke 3:20', 'Luke', 3, 20, 'بیا زندان ته د یحیی په اچولو سره هیرودیس یو بل بد کار هم وکړ. عیسی د تعمید غسل اخلي (متي ۳‏:‌۱۳‌‏-‌۱۷ او مرقوس ۱‏:‌۹‌‏-‌۱۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_20.mp3', '', 1761754199, 1761754199),
(35330, 'Luke 3:21', 'Luke', 3, 21, 'کله چې ټولو خلکو ته د تعمید غسل ورکړل شو، نو عیسی ته هم د تعمید غسل ورکړل شو. کله چې هغه دعا کوله نو د اسمان دروازه پرانیستل شوه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_21.mp3', '', 1761754199, 1761754199),
(35331, 'Luke 3:22', 'Luke', 3, 22, 'او روح القدس په هغه باندې د کوترې په شکل رانازل شو او د اسمان څخه یو اواز راغی: «ته زما ګران زوی یې. زه ستا نه خوشحاله یم.» د عیسی شجره (متي ۱‏:‌۱‌‏-‌۱۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_22.mp3', '', 1761754199, 1761754199),
(35332, 'Luke 3:23', 'Luke', 3, 23, 'عیسی شاوخوا د دېرشو کالو په عمر ؤ چې خپل خدمت یې پیل کړ او خلکو ګومان کاوه چې هغه د یوسف زوی دی. یوسف د هالي زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_23.mp3', '', 1761754199, 1761754199),
(35333, 'Luke 3:24', 'Luke', 3, 24, 'هالي د متات زوی ؤ، متات د لاوي زوی ؤ، لاوي د ملکي زوی ؤ، ملکي د ینا زوی ؤ، ینا د یوسف زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_24.mp3', '', 1761754199, 1761754199),
(35334, 'Luke 3:25', 'Luke', 3, 25, 'یوسف د متاتیا زوی ؤ، متاتیا د عاموس زوی ؤ، عاموس د ناحوم زوی ؤ، ناحوم د حسلي زوی ؤ، حسلي د نجي زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_25.mp3', '', 1761754199, 1761754199),
(35335, 'Luke 3:26', 'Luke', 3, 26, 'نجي د مات زوی ؤ، مات د متاتیا زوی ؤ، متاتیا د شمعي زوی ؤ، شمعي د یوسک زوی ؤ، یوسک د یوداه زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_26.mp3', '', 1761754199, 1761754199),
(35336, 'Luke 3:27', 'Luke', 3, 27, 'یوداه د یوحنا زوی ؤ، یوحنا د ریسا زوی ؤ، ریسا د زروبابل زوی ؤ، زروبابل د شالتي‌ییل زوی ؤ، شالتي‌ییل د نیري زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_27.mp3', '', 1761754199, 1761754199),
(35337, 'Luke 3:28', 'Luke', 3, 28, 'نیري د ملکي زوی ؤ، ملکي د آدي زوی ؤ، آدي د قوسام زوی ؤ، قوسام د ایلمودام زوی ؤ، ایلمودام د عیر زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_28.mp3', '', 1761754199, 1761754199),
(35338, 'Luke 3:29', 'Luke', 3, 29, 'عیر د یوشع زوی ؤ، یوشع د ایلعازر زوی ؤ، ایلعازر د یوریم زوی ؤ، یوریم د متات زوی ؤ، متات د لاوي زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_29.mp3', '', 1761754199, 1761754199),
(35339, 'Luke 3:30', 'Luke', 3, 30, 'لاوي د شمعون زوی ؤ، شمعون د یهودا زوی ؤ، یهودا د یوسف زوی ؤ، یوسف د یونان زوی ؤ، یونان د ایلیاقیم زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_30.mp3', '', 1761754199, 1761754199),
(35340, 'Luke 3:31', 'Luke', 3, 31, 'ایلیاقیم د ملیا زوی ؤ، ملیا د مینان زوی ؤ، مینان د متاتا زوی ؤ، متاتا د ناتان زوی ؤ، ناتان د داود زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_31.mp3', '', 1761754199, 1761754199),
(35341, 'Luke 3:32', 'Luke', 3, 32, 'داود د یسي زوی ؤ، یسي د عوبید زوی ؤ، عوبید د بوعز زوی ؤ، بوعز د شلمون زوی ؤ، شلمون د نحشون زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_32.mp3', '', 1761754199, 1761754199),
(35342, 'Luke 3:33', 'Luke', 3, 33, 'نحشون د عمیناداب زوی ؤ، عمیناداب د ادمین زوی ؤ، ادمین د ارام زوی ؤ، آرام د حزرون زوی ؤ، حزرون د فارز زوی ؤ، فارز د یهودا زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_33.mp3', '', 1761754199, 1761754199),
(35343, 'Luke 3:34', 'Luke', 3, 34, 'یهودا د یعقوب زوی ؤ، یعقوب د اسحاق زوی ؤ، اسحاق د ابراهیم زوی ؤ، ابراهیم د تارح زوی ؤ، تارح د ناحور زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_34.mp3', '', 1761754199, 1761754199),
(35344, 'Luke 3:35', 'Luke', 3, 35, 'ناحور د سروج زوی ؤ، سروج د رعو زوی ؤ، رعو د فلج زوی ؤ، فلج د عابر زوی ؤ، عابر د صالح زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_35.mp3', '', 1761754199, 1761754199),
(35345, 'Luke 3:36', 'Luke', 3, 36, 'صالح د قینان زوی ؤ، قینان د ارفکشاد زوی ؤ، ارفکشاد د سام زوی ؤ، سام د نوح زوی ؤ، نوح د لامک زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_36.mp3', '', 1761754199, 1761754199),
(35346, 'Luke 3:37', 'Luke', 3, 37, 'لامک د متوشالح زوی ؤ، متوشالح د خنوخ زوی ؤ، خنوخ د یارد زوی ؤ، یارد د مهللییل زوی ؤ، مهللییل د قینان زوی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_37.mp3', '', 1761754199, 1761754199),
(35347, 'Luke 3:38', 'Luke', 3, 38, 'قینان د انوش زوی ؤ، انوش د شیت زوی ؤ، شیت د آدم زوی ؤ، او آدم د خدای له طرفه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke3_verse_38.mp3', '', 1761754199, 1761754199),
(35348, 'John 18:1', 'John', 18, 1, 'کله چې عیسی دعا وکړه نو هغه د خپلو شاګردانو سره د ښار نه ووت او د قدرون د درې بلې خواته لاړ. هلته یو باغ ؤ چې عیسی او شاګردان یې ورننوتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_1.mp3', '', 1761754199, 1761754199),
(35349, 'John 18:2', 'John', 18, 2, 'یهودا خاین ته هغه ځای معلوم ؤ چې عیسی او شاګردان به یې اکثره وختونه په هغه ځای کې سره راټولېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_2.mp3', '', 1761754199, 1761754199),
(35350, 'John 18:3', 'John', 18, 3, 'یهودا یوه ډله رومي عسکر او د خدای د کور ساتونکي چې د مشرانو کاهنانو او فریسیانو له خوا رالېږل شوي وو، د ځان سره واخیستل او باغ ته ورغلل. د هغوی سره لاټینونه اوڅراغونه وو او په وسلو باندې سمبال وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_3.mp3', '', 1761754199, 1761754199),
(35351, 'John 18:4', 'John', 18, 4, 'که څه هم عیسی په دې پوهېده چې څه به ورته پېښیږي، خو بیاهم مخکې ورغی او د هغوی نه یې پوښتنه وکړه: «تاسو څوک لټوئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_4.mp3', '', 1761754199, 1761754199),
(35352, 'John 18:5', 'John', 18, 5, 'هغوی ځواب ورکړ: «ناصري عیسی.» عیسی وویل: «هماغه زه یم.» او یهودا خاین هم هلته د هغوی سره ولاړ ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_5.mp3', '', 1761754199, 1761754199),
(35353, 'John 18:6', 'John', 18, 6, 'کله چې عیسی هغوی ته وویل: «هماغه زه یم.» هغوی شاته شول او په ځمکه راوغورځېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_6.mp3', '', 1761754199, 1761754199),
(35354, 'John 18:7', 'John', 18, 7, 'عیسی یوځل بیا د هغوی نه پوښتنه وکړه: «تاسو څوک لټوئ؟» هغوی ځواب ورکړ: «ناصري عیسی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_7.mp3', '', 1761754199, 1761754199),
(35355, 'John 18:8', 'John', 18, 8, 'عیسی وویل: «ما تاسو ته وویل چې هماغه زه یم. که تاسو ما لټوئ نو دا نور پرېږدئ چې لاړ شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_8.mp3', '', 1761754199, 1761754199),
(35356, 'John 18:9', 'John', 18, 9, 'هغه دا وویل ترڅو هغه څه چې هغه ویلي وو هغه رښتیا شي: «ای پلاره، تا چې څوک ماته راسپارلي وو چې پام ورباندې وکړم د هغو نه مې یو هم له لاسه نه دی ورکړی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_9.mp3', '', 1761754199, 1761754199),
(35357, 'John 18:10', 'John', 18, 10, 'بیا شمعون پطروس چې توره ورسره وه، هغه یې راوویستله او د لوی کاهن په نوکر یې چې ملخوس نومېده، ګوزار وکړ او د هغه ښي غوږ یې پرې کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_10.mp3', '', 1761754199, 1761754199),
(35358, 'John 18:11', 'John', 18, 11, 'عیسی پطروس ته وویل: «خپله توره دې بېرته په خپل ځای کې کېږده. ایا د مصیبت هغه پیاله چې پلار راته راکړې ده ونه څښم؟» عیسی د حناس په مخکې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_11.mp3', '', 1761754199, 1761754199),
(35359, 'John 18:12', 'John', 18, 12, 'رومي عسکرو د خپل قوماندان او د یهودي ساتونکو سره عیسی ونیوه او کلک یې وتاړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_12.mp3', '', 1761754199, 1761754199),
(35360, 'John 18:13', 'John', 18, 13, 'هغه یې لومړی حناس ته چې د قیافا خسر ؤ او په هغه کال کې لوی کاهن ؤ، بوته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_13.mp3', '', 1761754199, 1761754199),
(35361, 'John 18:14', 'John', 18, 14, 'قیافا هماغه سړی ؤ چې یهودیانو مشرانو ته یې مشوره ورکړې وه چې په دې کې به د هغوی خیر وي چې یو کس د ټول قوم په خاطر مړ شي. پطروس د عیسی څخه انکار کوي (متي ۲۶‏:‌۶۹‌‏-‌۷۰ او مرقوس ۱۴‏:‌۶۶‌‏-‌۶۸ او لوقا ۲۲‏:‌۵۵‌‏-‌۵۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_14.mp3', '', 1761754199, 1761754199),
(35362, 'John 18:15', 'John', 18, 15, 'شمعون پطروس او یو بل شاګرد د لوی کاهن د کور تر حوېلۍ پورې عیسی پسې روان وو. څرنګه چې هغه شاګرد د لوی کاهن سره آشنایي لرله، نو هغه د عیسی سره د لوی کاهن د کور حوېلۍ ته ورننوت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_15.mp3', '', 1761754199, 1761754199),
(35363, 'John 18:16', 'John', 18, 16, 'خو پطروس دباندې په دروازه کې ودرېده. بیا هغه بل شاګرد چې د لوی کاهن سره یې آشنایي لرله بېرته راووت او د هغې ښځې سره یې چې د دروازې ساتونکې وه خبرې وکړې او پطروس یې دننه بوته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_16.mp3', '', 1761754199, 1761754199),
(35364, 'John 18:17', 'John', 18, 17, 'هغې چوکیدارې ښځې د پطروس نه پوښتنه وکړه: «ایا ته هم د دې سړي د شاګردانو څخه نه یې؟» پطروس ځواب ورکړ: «نه، زه نه یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_17.mp3', '', 1761754199, 1761754199),
(35365, 'John 18:18', 'John', 18, 18, 'نوکرانو او ساتونکو د سکرو اور بل کړی ؤ او ګردچاپېره ترې ولاړ وو او ځانونه یې تودول ځکه چې هوا سړه وه. پطروس هم د هغوی په څنګ کې ولاړ ؤ او ځان یې توداوه. لوی کاهن د عیسی نه څېړنې کوي (متي ۲۶‏:‌۵۹‌‏-‌۶۶ او مرقوس ۱۴‏:‌۵۵‌‏-‌۶۴ او لوقا ۲۲‏:‌۶۶‌‏-‌۷۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_18.mp3', '', 1761754199, 1761754199),
(35366, 'John 18:19', 'John', 18, 19, 'لوی کاهن د عیسی نه د هغه د شاګردانو او د هغه د تعلیم په هکله پوښتنه وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_19.mp3', '', 1761754199, 1761754199),
(35367, 'John 18:20', 'John', 18, 20, 'عیسی ځواب ورکړ: «ما د ټولو په مخکې ښکاره خبرې کړي دي. ما تل په کنیسو او د خدای په کور کې چې خلک په کې راټولیږي تعلیم ورکړی دی او هېڅکله مې پټې خبرې نه دي کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_20.mp3', '', 1761754199, 1761754199),
(35368, 'John 18:21', 'John', 18, 21, 'نو بیا ولې زما نه پوښتنه کوې؟ د هغو خلکو نه پوښتنه وکړه چې زما خبرې یې اورېدلي دي. هغوی پوهیږي چې ما څه ویلي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_21.mp3', '', 1761754199, 1761754199),
(35369, 'John 18:22', 'John', 18, 22, 'کله چې عیسی دا خبره وکړه نو د خدای د کور یو ساتونکي چې په هغه ځای کې ولاړ ؤ، عیسی ته په مخ څپېړه ورکړه او ویې ویل: «ته څنګه لوی کاهن ته داسې ځواب ورکوې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_22.mp3', '', 1761754199, 1761754199),
(35370, 'John 18:23', 'John', 18, 23, 'عیسی ځواب ورکړ: «که غلطه خبره مې کړې وي نو ثابته یې کړه او که سمه خبره مې کړې وي نو ولې مې وهې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_23.mp3', '', 1761754199, 1761754199),
(35371, 'John 18:24', 'John', 18, 24, 'بیا حناس هغه لاس تړلی لوی کاهن قیافا ته ولېږه. پطروس یوځل بیا د عیسی نه انکار کوي (متي ۲۶‏:‌۷۱‌‏-‌۷۵ او مرقوس ۱۴‏:‌۶۹‌‏-‌۷۲ او لوقا ۲۲‏:‌۵۸‌‏-‌۶۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_24.mp3', '', 1761754199, 1761754199),
(35372, 'John 18:25', 'John', 18, 25, 'په دې وخت کې شمعون پطروس په هغه ځای کې ولاړ ؤ او ځان یې توداوه، نو ځینو خلکو چې هلته ولاړ وو ورڅخه پوښتنه وکړه: «ایا ته هم د هغه د شاګردانو څخه نه یې؟» خو پطروس منکر شو او ویې ویل: «نه، زه نه یم»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_25.mp3', '', 1761754199, 1761754199),
(35373, 'John 18:26', 'John', 18, 26, 'د لوی کاهن د نوکرانو نه یو کس چې د هغه سړي خپلوان ؤ چې پطروس یې ورته غوږ پرې کړی ؤ، هغه ته وویل: «ایا ته مې د هغه سره په باغ کې ونه لیدلې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john18_verse_26.mp3', '', 1761754199, 1761754199),
