(35401, 'Matthew 12:14', 'Matthew', 12, 14, 'خو فریسیان د کنیسې نه ووتل او د عیسی د وژلو دپاره یې دسیسه جوړه کړه. د خدای غوره شوی خدمتګار', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_14.mp3', '', 1761754199, 1761754199),
(35402, 'Matthew 12:15', 'Matthew', 12, 15, 'کله چې عیسی د هغوی د دسیسې نه خبر شو، نو د هغه ځای څخه لاړ. ډېر خلک ورپسې روان شول او هغه ټول ناروغان روغ کړل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_15.mp3', '', 1761754199, 1761754199),
(35403, 'Matthew 12:16', 'Matthew', 12, 16, 'او هغوی ته یې امر وکړ چې هېچا ته ونه وایي چې هغه څوک دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_16.mp3', '', 1761754199, 1761754199),
(35404, 'Matthew 12:17', 'Matthew', 12, 17, 'ترڅو په دې ډول د اشعیا نبي هغه وینا رښتیا شي چې وایي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_17.mp3', '', 1761754199, 1761754199),
(35405, 'Matthew 12:18', 'Matthew', 12, 18, 'دا دی زما خدمتګار چې ما غوره کړی دی. هغه په ما باندې ګران دی او زه ترې خوشحاله یم. زه به په هغه باندې خپل روح نازل کړم او هغه به د نړۍ قومونه د خدای د قضاوت څخه خبروي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_18.mp3', '', 1761754199, 1761754199),
(35406, 'Matthew 12:19', 'Matthew', 12, 19, 'هغه به نه جنګ جګړې کوي او نه به چیغې وهي او نه به یې په کوڅو کې څوک اواز اوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_19.mp3', '', 1761754199, 1761754199),
(35407, 'Matthew 12:20', 'Matthew', 12, 20, 'هغه به کږه لوخه هم نه ماتوي او نه به ضعیفه ډېوه مړه کوي، ترڅو هغه انصاف بریالی کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_20.mp3', '', 1761754199, 1761754199),
(35408, 'Matthew 12:21', 'Matthew', 12, 21, 'د ټولو قومونو د هیلې سترګې به د هغه خواته وي. عیسی او بعلزبول یعنې شیطان (مرقوس ۳‏:‌۲۰‌‏-‌۳۰ او لوقا ۱۱‏:‌۱۴‌‏-‌۲۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_21.mp3', '', 1761754199, 1761754199),
(35409, 'Matthew 12:22', 'Matthew', 12, 22, 'په دې وخت کې خلکو یو ړوند او ګونګ سړی چې پېریانو نیولی ؤ عیسی ته راوست. عیسی هغه روغ کړ او هغه وکولای شول چې هم خبرې وکړي او هم وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_22.mp3', '', 1761754199, 1761754199),
(35410, 'Matthew 12:23', 'Matthew', 12, 23, 'ټول خلک حیران شول او ویې ویل: «ایا دا د داود زوی نه دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_23.mp3', '', 1761754199, 1761754199);